package com.termux.app.workspace;
import android.app.*;import android.view.*;import android.widget.*;import com.termux.app.TermuxActivity;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import org.robolectric.shadows.ShadowAlertDialog;import java.util.*;import java.util.concurrent.*;import java.io.File;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class)
public class EnvironmentInlineInstallTest {
 private TermuxActivity activity;private EnvironmentSetup setup;private CountDownLatch started,release,finished;private volatile File cancel;
 private View row(AlertDialog d){return d.getListView().getAdapter().getView(0,null,d.getListView());}
 private View tagged(View v,String tag){if(tag.equals(v.getTag()))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View hit=tagged(((ViewGroup)v).getChildAt(i),tag);if(hit!=null)return hit;}return null;}
 private void idle(){org.robolectric.Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();}
 @Before public void before(){activity=Robolectric.buildActivity(TermuxActivity.class).get();activity.getSharedPreferences("environment-install-attempts",0).edit().clear().commit();WorkspaceLanguage.select(activity,"en");started=new CountDownLatch(1);release=new CountDownLatch(1);finished=new CountDownLatch(1);setup=new EnvironmentSetup(activity,()->Arrays.asList(new WorkspaceEnvironments.Choice("proot:alpine","alpine","Alpine","/root",false)),(alias,update,marker)->{cancel=marker;update.accept("Downloading 40%");started.countDown();release.await(5,TimeUnit.SECONDS);boolean stopped=marker.exists();finished.countDown();return new EnvironmentSetup.Result(stopped?"ERROR:INSTALL_CANCELLED":"READY:environment\nREADY:shell\nCHECK:done",stopped?130:0);});}
 @After public void after(){release.countDown();setup.close();}
 private AlertDialog begin()throws Exception{setup.choose(c->fail("install must not select or close chooser"));AlertDialog d=ShadowAlertDialog.getLatestAlertDialog();View r=row(d);((TextView)tagged(r,"environment-install-alpine")).performClick();AlertDialog consent=ShadowAlertDialog.getLatestAlertDialog();consent.getButton(-1).performClick();idle();assertTrue("installer started",started.await(3,TimeUnit.SECONDS));idle();assertTrue("chooser stays open",d.isShowing());return d;}
 private void complete()throws Exception{release.countDown();assertTrue(finished.await(3,TimeUnit.SECONDS));for(int i=0;i<30;i++){Thread.sleep(10);idle();}}
 @Test public void dismissAndReopenKeepsRunningAndSuccessIsInline()throws Exception{
  AlertDialog first=begin();first.dismiss();assertFalse(cancel.exists());setup.choose(c->{});AlertDialog second=ShadowAlertDialog.getLatestAlertDialog();View current=row(second);TextView badge=(TextView)tagged(current,"environment-install-alpine");assertEquals("Stop",badge.getText().toString());assertEquals(View.VISIBLE,tagged(current,"environment-progress-alpine").getVisibility());complete();assertTrue(second.isShowing());View completed=row(second);TextView done=(TextView)tagged(completed,"environment-install-alpine");assertEquals("Installed",done.getText().toString());assertFalse(done.isEnabled());assertEquals(View.GONE,tagged(completed,"environment-progress-alpine").getVisibility());second.dismiss();
 }
 @Test public void stopRequestsOnlyThisJobAndDoesNotClaimInstalled()throws Exception{
  AlertDialog d=begin();View current=row(d);assertEquals(View.GONE,tagged(current,"environment-install-details-alpine").getVisibility());TextView badge=(TextView)tagged(current,"environment-install-alpine");badge.performClick();badge=(TextView)tagged(row(d),"environment-install-alpine");assertTrue(cancel.exists());assertEquals("Stopping…",badge.getText().toString());assertFalse(badge.isEnabled());complete();current=row(d);badge=(TextView)tagged(current,"environment-install-alpine");assertEquals("Resume",badge.getText().toString());assertTrue(badge.isEnabled());assertEquals(View.VISIBLE,tagged(current,"environment-progress-alpine").getVisibility());View details=tagged(current,"environment-install-details-alpine");assertEquals(View.VISIBLE,details.getVisibility());details.performClick();AlertDialog log=ShadowAlertDialog.getLatestAlertDialog();assertTrue(((TextView)tagged(log.getWindow().getDecorView(),"environment-install-log-text")).getText().toString().contains("ERROR:INSTALL_CANCELLED"));assertNotNull(tagged(log.getWindow().getDecorView(),"environment-install-log-download"));log.getButton(-2).performClick();assertTrue(d.isShowing());assertTrue(cancel.exists()==false);d.dismiss();
 }
 @Test public void retainedDownloadShowsResumeAfterChooserRecreation()throws Exception{
  File state=new File(activity.getFilesDir(),".environment-control/downloads/alpine/state.json");assertTrue(state.getParentFile().mkdirs());try(java.io.FileWriter w=new java.io.FileWriter(state)){w.write("{}");}
  setup.choose(c->fail("not installed"));AlertDialog d=ShadowAlertDialog.getLatestAlertDialog();TextView badge=(TextView)tagged(row(d),"environment-install-alpine");assertEquals("Resume",badge.getText().toString());badge.performClick();AlertDialog consent=ShadowAlertDialog.getLatestAlertDialog();assertEquals("Resume",consent.getButton(-1).getText().toString());consent.dismiss();d.dismiss();
  setup.choose(c->{});d=ShadowAlertDialog.getLatestAlertDialog();assertEquals("Resume",((TextView)tagged(row(d),"environment-install-alpine")).getText().toString());d.dismiss();assertTrue(state.delete());
 }


 @Test public void cancelledNativeInstallCanBeRetriedAfterChooserObjectRecreation()throws Exception{
  AlertDialog d=begin();((TextView)tagged(row(d),"environment-install-alpine")).performClick();complete();d.dismiss();setup.close();
  setup=new EnvironmentSetup(activity,()->Arrays.asList(new WorkspaceEnvironments.Choice("proot:alpine","alpine","Alpine","/root",false)));setup.choose(c->{});d=ShadowAlertDialog.getLatestAlertDialog();assertEquals("Resume",((TextView)tagged(row(d),"environment-install-alpine")).getText().toString());View details=tagged(row(d),"environment-install-details-alpine");assertEquals(View.VISIBLE,details.getVisibility());details.performClick();for(int i=0;i<30;i++){Thread.sleep(10);idle();}AlertDialog log=ShadowAlertDialog.getLatestAlertDialog();assertNotSame(d,log);assertTrue(((TextView)tagged(log.getWindow().getDecorView(),"environment-install-log-text")).getText().toString().contains("Environment: alpine"));log.dismiss();d.dismiss();
 }

 @Test public void nativeSuccessClearsLegacyMetadataButPreservesDownloadedParts()throws Exception{
  AlertDialog d=begin();EnvironmentInstallLog.save(activity.getFilesDir(),"alpine","previous failure");File folder=new File(activity.getFilesDir(),".environment-control/downloads/alpine");folder.mkdirs();File old=new File(folder,"state.json"),part=new File(folder,"retained.part");try(java.io.FileWriter w=new java.io.FileWriter(old)){w.write("{}");}try(java.io.FileWriter w=new java.io.FileWriter(part)){w.write("retained");}complete();assertFalse(old.exists());assertTrue(part.exists());assertFalse(EnvironmentInstallLog.exists(activity.getFilesDir(),"alpine"));assertEquals(View.GONE,tagged(row(d),"environment-install-details-alpine").getVisibility());assertEquals("Installed",((TextView)tagged(row(d),"environment-install-alpine")).getText().toString());d.dismiss();
 }
 @Test public void failedAttemptDetailsAppearBeforeResumeForEveryEnvironment()throws Exception{
  setup.close();List<WorkspaceEnvironments.Choice> choices=new ArrayList<>();for(String alias:new String[]{"ubuntu","ubuntu-ai","debian","alpine","archlinux","fedora","opensuse","void"}){choices.add(new WorkspaceEnvironments.Choice("proot:"+alias,alias,alias,"/root",false));EnvironmentInstallLog.save(activity.getFilesDir(),alias,EnvironmentInstallLog.report(alias,1,"Failed to install: "+alias));activity.getSharedPreferences("environment-install-attempts",0).edit().putBoolean("pending."+alias,true).commit();}
  setup=new EnvironmentSetup(activity,()->choices,(alias,update,marker)->{fail("viewing diagnostics must never install");return null;});setup.choose(c->fail("details must not select session"));AlertDialog d=ShadowAlertDialog.getLatestAlertDialog();
  for(int i=0;i<choices.size();i++){String alias=choices.get(i).alias;View card=d.getListView().getAdapter().getView(i,null,d.getListView());View more=tagged(card,"environment-install-details-"+alias),resume=tagged(card,"environment-install-"+alias);assertEquals(alias,View.VISIBLE,more.getVisibility());assertEquals("Resume",((TextView)resume).getText().toString());ViewGroup parent=(ViewGroup)more.getParent();assertSame(parent,resume.getParent());assertTrue(parent.indexOfChild(more)<parent.indexOfChild(resume));}
  d.dismiss();
 }
}
